-- Production shapes (2026-11-20, read from information_schema) of the tables the
-- lab migration touches, trimmed to the columns it uses. Structure only, no data.
create table public.audit_log (id uuid not null default gen_random_uuid() primary key, table_name text, action text, record_id text, user_id uuid, user_role text, old_value jsonb, new_value jsonb, created_at timestamp with time zone not null default timezone('utc'::text, now()), tenant_id uuid, updated_at timestamp with time zone default now(), created_by uuid, is_deleted boolean default false);
create table public.capabilities (id uuid not null default gen_random_uuid() primary key, module text not null, resource text not null, action text not null, description text, created_at timestamp with time zone not null default now(), unique(module,resource,action));
create table public.tenants (id uuid not null default gen_random_uuid() primary key, slug text not null, name text not null, facility_type text default 'clinic'::text, status text, is_synthetic boolean not null default false);
create table public.hospitals (id uuid not null default gen_random_uuid() primary key, name text not null, subdomain text not null, type text not null default 'general'::text, settings jsonb, facility_kind text not null default 'hospital');
create table public.profiles (id uuid not null primary key, hospital_id uuid, full_name text, role text not null default 'patient'::text, email text, tenant_id uuid, is_deleted boolean default false);
create table public.persons (id uuid not null default gen_random_uuid() primary key, synapse_id text not null, full_name text not null);
create table public.patients (id uuid not null default gen_random_uuid() primary key, hospital_id uuid, mrn text not null, dob date, sex text, phone text, full_name text, tenant_id uuid references tenants(id), created_by uuid, is_deleted boolean default false, person_id uuid, is_synthetic boolean not null default false, data_classification text);
create table public.encounters (id uuid not null default gen_random_uuid() primary key, hospital_id uuid, patient_id uuid references patients(id), clinician_id uuid, chief_complaint text, metadata jsonb, created_at timestamp with time zone not null default now(), tenant_id uuid, is_deleted boolean default false, status text not null default 'open'::text, person_id uuid, correlation_id uuid, is_synthetic boolean not null default false);
create table public.hospital_modules (id uuid not null default gen_random_uuid() primary key, hospital_id uuid, tenant_id uuid, module_key text not null, is_active boolean default false);
create table public.platform_billing_config (key text not null primary key, value jsonb not null default '{}'::jsonb);
create table public.role_capabilities (id uuid not null default gen_random_uuid() primary key, role text not null, facility_type text not null default 'any'::text, capability_id uuid not null references capabilities(id), granted_at timestamp with time zone not null default now(), unique(role, facility_type, capability_id));
create table public.synapse_sessions (id uuid not null default gen_random_uuid() primary key, user_id uuid not null, token_hash text not null, app text not null, expires_at timestamp with time zone not null, revoked_at timestamp with time zone);
create table public.lab_accession_counters (tenant_id uuid not null, facility_code text not null, day_key text not null, last_value integer not null default 0, primary key (tenant_id, facility_code, day_key));
create table public.lab_orders (id uuid not null default gen_random_uuid() primary key, tenant_id uuid not null references tenants(id) on delete cascade, encounter_id uuid not null references encounters(id), patient_id uuid not null references patients(id), loinc_code text, test_name text not null, urgency text not null default 'ROUTINE'::text, status text not null default 'ordered'::text check (status in ('ordered','collected','processing','resulted','verified','cancelled')), ordered_by uuid not null references profiles(id), ordered_at timestamp with time zone not null default now(), collected_at timestamp with time zone, resulted_at timestamp with time zone, verified_at timestamp with time zone, verified_by uuid references profiles(id), insurance_covered boolean not null default false, created_at timestamp with time zone not null default now(), person_id uuid, workflow_status text, accession_number text, barcode text, specimen_id uuid, rejection_reason text, rejection_note text, correlation_id uuid, care_plan_id uuid, is_synthetic boolean not null default false, simulation_run_id uuid, data_classification text, replaces_lab_order_id uuid, unique (id, tenant_id));
create table public.lab_reference_ranges (id uuid not null default gen_random_uuid() primary key, loinc_code text not null, test_name text not null, unit text not null, sex text, age_min_years numeric, age_max_years numeric, low numeric not null, high numeric not null, critical_low numeric, critical_high numeric, country_pack text not null default 'UG'::text);
create unique index lab_reference_ranges_natural_key on public.lab_reference_ranges (loinc_code, coalesce(sex, ''), coalesce(age_min_years, -1), coalesce(age_max_years, -1), country_pack);
insert into public.lab_reference_ranges (loinc_code, test_name, unit, low, high, critical_low, critical_high) values ('2345-7', 'Glucose', 'mmol/L', 3.9, 6.1, 2.2, 30.0), ('2823-3', 'Potassium', 'mmol/L', 3.5, 5.1, 2.5, 6.5);
create table public.lab_results (id uuid not null default gen_random_uuid() primary key, encounter_id uuid not null references encounters(id), lab_technician_id uuid references profiles(id), loinc_code text, test_name text not null, value text not null, unit text, reference_range text, flag text, notes text, created_at timestamp with time zone not null default now(), tenant_id uuid not null, updated_at timestamp with time zone default now(), is_deleted boolean default false, numeric_value numeric, abnormal_flag text, analyzer text, verified_by uuid, verified_at timestamp with time zone, provenance text, is_synthetic boolean not null default false, result_source text, entered_by uuid, entered_at timestamp with time zone default now(), lab_order_id uuid not null, patient_id uuid not null, result_value text, status text not null default 'preliminary' check (status in ('preliminary','final','corrected','cancelled')), is_critical boolean not null default false, is_abnormal boolean not null default false, version integer not null default 1, released_to_patient_at timestamp with time zone, critical_scientist_ack_at timestamp with time zone, critical_scientist_ack_by uuid, critical_clinician_ack_at timestamp with time zone, critical_clinician_ack_by uuid, unique (tenant_id, lab_order_id), foreign key (lab_order_id, tenant_id) references lab_orders(id, tenant_id));
create table public.lab_specimens (id uuid not null default gen_random_uuid() primary key, tenant_id uuid not null, person_id uuid, patient_id uuid, encounter_id uuid, lab_order_id uuid, accession_number text not null, barcode text, specimen_type text, status text not null default 'collected' check (status in ('ordered','collected','in_lab','on_analyzer','resulted','verified','rejected','disposed')), collected_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), collected_by uuid, container text, volume_ml numeric, condition text, received_at timestamp with time zone, unique (tenant_id, accession_number));
create table public.lab_reports (id uuid not null default gen_random_uuid() primary key, tenant_id uuid not null, facility_id uuid, patient_id uuid not null, encounter_id uuid, lab_order_id uuid not null, clinical_result_id uuid not null references lab_results(id), accession text not null, status text not null, version integer not null default 1, report_type text not null default 'LAB_RESULT'::text, generated_at timestamp with time zone not null default now(), generated_by uuid, verified_by uuid, released_at timestamp with time zone not null, supersedes_report_id uuid references lab_reports(id), amendment_reason text, template_version text not null default 'lab-report.v1'::text, html_snapshot text not null, artifact_path text, content_hash text not null, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), unique (tenant_id, lab_order_id, version));
create table public.lab_result_amendments (id uuid not null default gen_random_uuid() primary key, tenant_id uuid not null, result_id uuid not null, lab_order_id uuid, previous_value text not null, previous_status text not null, new_value text not null, reason text not null, amended_by uuid, amended_at timestamp with time zone not null default now(), is_synthetic boolean not null default false);
create table public.lab_critical_acknowledgements (id uuid not null default gen_random_uuid() primary key, tenant_id uuid not null, result_id uuid not null, lab_order_id uuid, patient_id uuid, acknowledged_by uuid not null, acknowledged_at timestamp with time zone not null default now(), note text, is_synthetic boolean not null default false);
create table public.lab_devices (id uuid primary key default gen_random_uuid(), tenant_id uuid not null);
create table public.lab_device_messages (id uuid primary key default gen_random_uuid(), tenant_id uuid not null);
create table public.lab_result_staging (id uuid not null default gen_random_uuid() primary key, tenant_id uuid not null, device_id uuid references lab_devices(id), device_message_id uuid references lab_device_messages(id), lab_order_id uuid, specimen_id uuid, accession_number text, analyzer_code text, mapped_loinc text, mapped_test_name text, value text, unit text, flags jsonb not null default '{}'::jsonb, instrument_flags jsonb not null default '{}'::jsonb, status text not null default 'RECEIVED'::text, correlation_id text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create function public.has_capability(p_role text, p_facility_type text, p_module text, p_resource text, p_action text) returns boolean language sql stable security definer set search_path to 'public' as $$ select exists (select 1 from role_capabilities rc join capabilities c on c.id = rc.capability_id where rc.role = p_role and c.module = p_module and c.resource = p_resource and c.action = p_action and (rc.facility_type = p_facility_type or rc.facility_type = 'any')); $$;
create function public.has_feature(p_tenant_id uuid, p_feature text) returns boolean language sql stable as $$ select true $$;
create function public.current_tenant_id() returns uuid language sql stable as $$ select tenant_id from profiles where id = auth.uid() $$;
create function public.is_platform_admin() returns boolean language sql stable as $$ select false $$;
